(4021240, 575140, 34041, '<td valign="top">Very nice. Great backlights on the needles. They seem to clow. 7 from me.</td>', 'Very nice. Great backlights on the needles. They seem to clow. 7 from me.', '2007-08-22 14:21:12.000000', NULL, 1),
