(4024984, 575319, 77196, '<td valign="top">Backlight is when the light is behind your subject - not you. Other than that, this is a beautiful picture. Rainbows are not easy to capture nicely, and you''ve done an excellent job.</td>', 'Backlight is when the light is behind your subject - not you. Other than that, this is a beautiful picture. Rainbows are not easy to capture nicely, and you''ve done an excellent job.', '2007-08-23 21:52:59.000000', NULL, 1),
(4024990, 575283, 77196, '<td valign="top">This is a stretch for the challenge. I guess technically this is back light (as long as you don''t read the description too close...) Overall, this is an interesting shot. The lack of bright color leaves it a bit bland, but the texture of the rock wall, the green on the wall, and the HUGE shadow make it a "2nd look" picture.</td>', 'This is a stretch for the challenge. I guess technically this is back light (as long as you don''t read the description too close...) Overall, this is an interesting shot. The lack of bright color leaves it a bit bland, but the texture of the rock wall, the green on the wall, and the HUGE shadow make it a "2nd look" picture.', '2007-08-23 21:57:36.000000', NULL, 1),
(4024999, 575286, 77196, '<td valign="top">DNMC - looks like it went silhouette on you. This is a nice and interesting picture.</td>', 'DNMC - looks like it went silhouette on you. This is a nice and interesting picture.', '2007-08-23 22:01:54.000000', NULL, 1),
(4025004, 575324, 77196, '<td valign="top">DNMC silhouetted I like your use of black against the blue. Nice line of table(?).</td>', 'DNMC silhouetted I like your use of black against the blue. Nice line of table(?).', '2007-08-23 22:06:27.000000', NULL, 1),
(4025005, 575316, 77196, '<td valign="top">Lime green isn''t a favorite color of many people. That, combined with a dead (or almost dead) rose that is mostly OOF does not make a pleasing shot. I prefer a larger depth of field, but your lighting in this shot is very nice.</td>', 'Lime green isn''t a favorite color of many people. That, combined with a dead (or almost dead) rose that is mostly OOF does not make a pleasing shot. I prefer a larger depth of field, but your lighting in this shot is very nice.', '2007-08-23 22:09:04.000000', NULL, 1),
(4025006, 574715, 77196, '<td valign="top">Bummer the horse''s head has the tree behind it. This would have been a much better shot without the tree, and the grass / brush providing background and definition for the head.</td>', 'Bummer the horse''s head has the tree behind it. This would have been a much better shot without the tree, and the grass / brush providing background and definition for the head.', '2007-08-23 22:10:28.000000', NULL, 1),
