(4035589, 575128, 35350, '<td valign="top">Very interesting.  I would suggect a little lower setting on the foreground flash; maybe even a closer crop on the people.</td>', 'Very interesting.  I would suggect a little lower setting on the foreground flash; maybe even a closer crop on the people.', '2007-08-28 14:39:46.000000', NULL, 1),
(4035593, 575112, 39137, '<td valign="top">I like the coloring against the black background. Good lighting. Well done meeting the criteria of the challenge.</td>', 'I like the coloring against the black background. Good lighting. Well done meeting the criteria of the challenge.', '2007-08-28 14:48:17.000000', NULL, 1),
(4035705, 575469, 69368, '<td valign="top">so elegant, so exellent lighting, so nice composition, so great reflection...<br/>A winner-pic!<br/><br/><i>Message edited by author 2007-08-29 02:55:18.</i></td>', 'so elegant, so exellent lighting, so nice composition, so great reflection...A winner-pic!', '2007-08-28 15:59:19.000000', '2007-08-29 03:55:18.000000', 1),
(4035721, 572936, 83395, '<td valign="top">Very cool.  I like the contrast and lighting.</td>', 'Very cool.  I like the contrast and lighting.', '2007-08-28 16:09:44.000000', NULL, 1),
(4035728, 575202, 69368, '<td valign="top">very beautiful and well done!</td>', 'very beautiful and well done!', '2007-08-28 16:12:10.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4035744, 575332, 66952, '<td valign="top">Great job balancing the backlight and the bulb filament.</td>', 'Great job balancing the backlight and the bulb filament.', '2007-08-28 16:21:41.000000', NULL, 1),
(4035747, 575470, 66952, '<td valign="top">I don''t know how you did this, but it''s very cool. I assume you didn''t burn the house down ;-)</td>', 'I don''t know how you did this, but it''s very cool. I assume you didn''t burn the house down ;-)', '2007-08-28 16:23:22.000000', NULL, 1),
(4035748, 573433, 66952, '<td valign="top">Nice detail with the flower stem.</td>', 'Nice detail with the flower stem.', '2007-08-28 16:23:53.000000', NULL, 1),
(4035760, 575353, 83395, '<td valign="top">I really like the image.  Clean, nicely done.</td>', 'I really like the image.  Clean, nicely done.', '2007-08-28 16:32:31.000000', NULL, 1),
(4035798, 575283, 38924, '<td valign="top">I''m not sure the subject is backlit.  From the viewers perspective, the subject is being lit from the front (even though we''re looking at their back).</td>', 'I''m not sure the subject is backlit.  From the viewers perspective, the subject is being lit from the front (even though we''re looking at their back).', '2007-08-28 16:49:46.000000', NULL, 1),
(4035801, 575061, 38924, '<td valign="top">Very cool idea.  I wish the web was closer, though.</td>', 'Very cool idea.  I wish the web was closer, though.', '2007-08-28 16:54:43.000000', NULL, 1),
(4035932, 575071, 26001, '<td valign="top">beautiful colors. could have been improved by a couple of usm passes (with small radius). i like the patterns too.</td>', 'beautiful colors. could have been improved by a couple of usm passes (with small radius). i like the patterns too.', '2007-08-28 18:00:49.000000', NULL, 1),
(4035935, 575234, 26001, '<td valign="top">beautiful curves and nice colors.</td>', 'beautiful curves and nice colors.', '2007-08-28 18:01:42.000000', NULL, 1),
(4035942, 573405, 26001, '<td valign="top">sharpness is outstanding and the background (fountain or waterfall?) makes this shot interesting. just a little too hot in some areas though.</td>', 'sharpness is outstanding and the background (fountain or waterfall?) makes this shot interesting. just a little too hot in some areas though.', '2007-08-28 18:03:36.000000', NULL, 1),
(4036005, 575199, 46832, '<td valign="top">Nice photo and a very clever title.</td>', 'Nice photo and a very clever title.', '2007-08-28 18:37:51.000000', NULL, 1),
(4036006, 573852, 46832, '<td valign="top">Very clever.  I like it.</td>', 'Very clever.  I like it.', '2007-08-28 18:37:56.000000', NULL, 1),
(4036010, 575470, 46832, '<td valign="top">Clever and imaginative.  Good use of backlighting.</td>', 'Clever and imaginative.  Good use of backlighting.', '2007-08-28 18:39:04.000000', NULL, 1),
(4036012, 575202, 46832, '<td valign="top">Clever ... and nicely done.</td>', 'Clever ... and nicely done.', '2007-08-28 18:39:50.000000', NULL, 1),
(4036019, 574737, 46832, '<td valign="top">I think that the rules allow you to remove that dust spec.</td>', 'I think that the rules allow you to remove that dust spec.', '2007-08-28 18:44:26.000000', NULL, 1),
(4036144, 575197, 80807, '<td valign="top">VERY CREATIVE!!!  As well as being tech. correct.  Can I give it a 12?</td>', 'VERY CREATIVE!!!  As well as being tech. correct.  Can I give it a 12?', '2007-08-28 19:26:25.000000', NULL, 1),
(4036201, 575537, 49930, '<td valign="top">Fantatsic interplay of colour / tone/ reflection. A beautifully executed shot and PP. Well done  - 10<br/>I have added this to my favourites ( I never thought I awould add a shot of eggs LOL - but a great shot is a great shot)</td>', 'Fantatsic interplay of colour / tone/ reflection. A beautifully executed shot and PP. Well done  - 10I have added this to my favourites ( I never thought I awould add a shot of eggs LOL - but a great shot is a great shot)', '2007-08-28 19:57:45.000000', NULL, 1),
(4036204, 574514, 49930, '<td valign="top">Very artistic - beautifully executed. Love the combination of flower and glass. Absolutely lovely - 10</td>', 'Very artistic - beautifully executed. Love the combination of flower and glass. Absolutely lovely - 10', '2007-08-28 19:59:22.000000', NULL, 1),
(4036206, 572979, 49930, '<td valign="top">We should all be eating it. Great  shot  - should do well - 10</td>', 'We should all be eating it. Great  shot  - should do well - 10', '2007-08-28 20:00:24.000000', NULL, 1),
(4036209, 575165, 49930, '<td valign="top">A lovely image. I had to come back to this one. Although the flowers look like they lit by another source  - the sun in the clouds fit the theme. 10</td>', 'A lovely image. I had to come back to this one. Although the flowers look like they lit by another source  - the sun in the clouds fit the theme. 10', '2007-08-28 20:02:48.000000', NULL, 1),
(4036222, 574795, 66952, '<td valign="top">Nice. One of my top picks.</td>', 'Nice. One of my top picks.', '2007-08-28 20:06:53.000000', NULL, 1),
(4036230, 573065, 66952, '<td valign="top">There''s a lot to like about this shot. The backlighting is nice, especially on her eyelashes, and her expression is good. The trouble with backlighting, though, is that it''s hard to control. Her forehead and the top of her chin are both a bit blown out, and it looks like lens flare has taken over most of her face. Sometimes that stuff can be fixed during post processing, but the most effective thing is to shoot when the sun is less intense, or shoot from a slightly different angle, to try to control things better.</td>', 'There''s a lot to like about this shot. The backlighting is nice, especially on her eyelashes, and her expression is good. The trouble with backlighting, though, is that it''s hard to control. Her forehead and the top of her chin are both a bit blown out, and it looks like lens flare has taken over most of her face. Sometimes that stuff can be fixed during post processing, but the most effective thing is to shoot when the sun is less intense, or shoot from a slightly different angle, to try to control things better.', '2007-08-28 20:12:25.000000', NULL, 1),
(4036231, 575401, 66952, '<td valign="top">The reflections are lovely. The backlighting effect may be a bit muted for a backlighting challenge, but it''s still there. Nice.</td>', 'The reflections are lovely. The backlighting effect may be a bit muted for a backlighting challenge, but it''s still there. Nice.', '2007-08-28 20:15:16.000000', NULL, 1),
(4036232, 575374, 66952, '<td valign="top">Simple and effective.</td>', 'Simple and effective.', '2007-08-28 20:16:28.000000', NULL, 1),
(4036234, 574268, 66952, '<td valign="top">The effect is great, but it looks like the flower is in focus, and the butterfly is soft. It would be nice if both could be sharp.</td>', 'The effect is great, but it looks like the flower is in focus, and the butterfly is soft. It would be nice if both could be sharp.', '2007-08-28 20:18:11.000000', NULL, 1),
(4036298, 575266, 51538, '<td valign="top">To me, perhaps the best image in this challenge. It is a memorable view. 9.</td>', 'To me, perhaps the best image in this challenge. It is a memorable view. 9.', '2007-08-28 20:54:30.000000', NULL, 1),
(4036300, 574618, 51538, '<td valign="top">What a nice moment you have recorded.  The back lighting and bokeh enhances the image too. 9.</td>', 'What a nice moment you have recorded.  The back lighting and bokeh enhances the image too. 9.', '2007-08-28 20:55:26.000000', NULL, 1),
(4036304, 574476, 51538, '<td valign="top">Wonderful.  Appeals to my age old instinct to travel - into the golden future. 10.</td>', 'Wonderful.  Appeals to my age old instinct to travel - into the golden future. 10.', '2007-08-28 20:56:12.000000', NULL, 1),
(4036305, 575544, 51538, '<td valign="top">Exquisite moment in time. 8.</td>', 'Exquisite moment in time. 8.', '2007-08-28 20:56:38.000000', NULL, 1),
(4036306, 575469, 51538, '<td valign="top">Of this genre, your photo is one of the nicest I have seen.  Lovely composition. 8.</td>', 'Of this genre, your photo is one of the nicest I have seen.  Lovely composition. 8.', '2007-08-28 20:57:13.000000', NULL, 1),
(4036309, 572774, 51538, '<td valign="top">Vitality recorded and a very nice framing too. 9.</td>', 'Vitality recorded and a very nice framing too. 9.', '2007-08-28 20:57:44.000000', NULL, 1),
(4036438, 573405, 67697, '<td valign="top">Love the contrast.  The details of the statue really command your attention.</td>', 'Love the contrast.  The details of the statue really command your attention.', '2007-08-28 22:14:43.000000', NULL, 1),
(4036444, 575165, 67697, '<td valign="top">The light on the red really helps the flowers jump out from the background.  Beautiful sky!</td>', 'The light on the red really helps the flowers jump out from the background.  Beautiful sky!', '2007-08-28 22:16:12.000000', NULL, 1),
(4036453, 573552, 67697, '<td valign="top">lol that is how i feel some days.  Interesting composition and the curtains add something fun to the background.</td>', 'lol that is how i feel some days.  Interesting composition and the curtains add something fun to the background.', '2007-08-28 22:17:49.000000', NULL, 1),
(4036476, 575471, 67697, '<td valign="top">Love the dark tones.  Looks like a picture that''s part of a story book.</td>', 'Love the dark tones.  Looks like a picture that''s part of a story book.', '2007-08-28 22:22:53.000000', NULL, 1),
(4036480, 575139, 67697, '<td valign="top">Beautiful lighting.  Adds the right drama for the moment you captured.</td>', 'Beautiful lighting.  Adds the right drama for the moment you captured.', '2007-08-28 22:24:10.000000', NULL, 1),
(4036499, 572812, 67697, '<td valign="top">Beautiful photo.  Love the "lit" lamps.</td>', 'Beautiful photo.  Love the "lit" lamps.', '2007-08-28 22:32:00.000000', NULL, 1),
(4036503, 573852, 58235, '<td valign="top">great idea</td>', 'great idea', '2007-08-28 22:35:37.000000', NULL, 1),
